-- =============================================================================
-- Carga del Analisis de riesgo de COMPRAS (version 2: 2 riesgos en rojo, responsables y fechas).
-- Lo deja a nombre del comprador (fburgos@elsauz.com; si no existe ese correo, el comprador activo).
-- Si ya se habia cargado, lo ACTUALIZA (mismo folio). Despues se edita normal desde el portal.
-- Como aplicarlo: pega este archivo COMPLETO en SQL Editor y presiona Run.
-- =============================================================================
do $carga$
declare v_id uuid; v_ar uuid;
begin
  select id into v_id from public.profiles where lower(correo) = 'fburgos@elsauz.com' and activo;
  if v_id is null then
    select id into v_id from public.profiles where rol = 'comprador' and activo order by created_at limit 1;
  end if;
  if v_id is null then raise exception 'No encontre al comprador en el portal'; end if;
  -- Se registra como si lo hubiera capturado el comprador (autor y area).
  perform set_config('request.jwt.claim.sub', v_id::text, true);
  perform set_config('request.jwt.claims', json_build_object('sub', v_id, 'role', 'authenticated')::text, true);
  select id into v_ar from public.riesgo_analisis where created_by = v_id and proceso = 'Compras' order by created_at limit 1;
  if v_ar is null then
    insert into public.riesgo_analisis (proceso, fecha, actividades, created_by)
    values ('Compras', public.local_today(), $json$[{"id": "d8x8t1fzjzst", "actividad": "Selección y evaluación de proveedores", "modos": [{"id": "syblh5sufzas", "modo": "Proveedor sin evaluación / no aprobado", "efectos": "Paro por material no conforme, rechazo de cliente, hallazgo de auditoría", "vinculado": "Proveedor", "tipo": "riesgo", "severidad": 4, "causas": "Alta de un proveedor nuevo por urgencia sin evaluarlo antes", "ocurrencia": 1, "prevencion": "Evaluación de proveedores en el portal antes de comprar", "deteccion_ctrl": "Revisión del catálogo de proveedores evaluados", "deteccion": 2, "acciones": "Mantener: no emitir OC a un proveedor sin evaluación vigente.", "responsable": "Fabian Burgos (Compras)", "fecha_terminacion": "", "fecha_verificacion": "", "acciones_tomadas": "", "severidad_r": null, "ocurrencia_r": null, "deteccion_r": null}, {"id": "5saz4e6qq3qy", "modo": "Proveedor único sin justificación", "efectos": "Riesgo de desabasto, dependencia total del proveedor, sin negociación de precio", "vinculado": "Proveedor", "tipo": "riesgo", "severidad": 4, "causas": "Artículos que solo surte un proveedor (en especial de importación) sin alterno identificado", "ocurrencia": 3, "prevencion": "Conocimiento del comprador de proveedores alternos", "deteccion_ctrl": "Se detecta cuando el proveedor falla o sube el precio", "deteccion": 3, "acciones": "Identificar los artículos de proveedor único, documentar la justificación y buscar al menos un proveedor alterno.", "responsable": "Fabian Burgos (Compras)", "fecha_terminacion": "", "fecha_verificacion": "", "acciones_tomadas": "", "severidad_r": null, "ocurrencia_r": null, "deteccion_r": null}]}, {"id": "cxso7y97kndt", "actividad": "Solicitud de cotizaciones a proveedores", "modos": [{"id": "j4pj1bsvoo5o", "modo": "Compra sin cotización comparativa", "efectos": "Sobreprecio, pérdida de margen, favoritismos, hallazgo ISO", "vinculado": "Cláusula ISO 9001", "tipo": "riesgo", "severidad": 3, "causas": "Por tiempo o por costumbre se compra al mismo proveedor sin comparar (se hace solo a veces)", "ocurrencia": 3, "prevencion": "Catálogo de proveedores en el portal", "deteccion_ctrl": "Revisión de la OC con la gerente", "deteccion": 3, "acciones": "Definir un monto a partir del cual se piden mínimo 2 cotizaciones y dejarlas registradas con la compra.", "responsable": "Fabian Burgos (Compras)", "fecha_terminacion": "", "fecha_verificacion": "", "acciones_tomadas": "", "severidad_r": null, "ocurrencia_r": null, "deteccion_r": null}, {"id": "1r82tzvsysat", "modo": "Especificación de compra incompleta", "efectos": "Material incorrecto, retrabajo, devoluciones, retraso operativo", "vinculado": "Requisito del cliente", "tipo": "riesgo", "severidad": 4, "causas": "La solicitud del vendedor llega sin ficha técnica, foto o medidas completas", "ocurrencia": 2, "prevencion": "Solicitud de cotización en el portal con descripción, imagen o liga de referencia", "deteccion_ctrl": "Aclaraciones con el vendedor en el chat de la partida", "deteccion": 3, "acciones": "Pedir ficha técnica o muestra al proveedor en artículos nuevos antes de la primera compra.", "responsable": "Fabian Burgos (Compras)", "fecha_terminacion": "", "fecha_verificacion": "", "acciones_tomadas": "", "severidad_r": null, "ocurrencia_r": null, "deteccion_r": null}, {"id": "ivi04nb1o6su", "modo": "Cotización vencida o sin condiciones", "efectos": "Variación de precio al facturar, sin garantía", "vinculado": "Proveedor", "tipo": "riesgo", "severidad": 3, "causas": "Precios de importación que cambian por flete y tipo de cambio; cotizaciones sin vigencia ni Incoterm", "ocurrencia": 3, "prevencion": "Ninguno formal", "deteccion_ctrl": "Se detecta al recibir la factura del proveedor", "deteccion": 3, "acciones": "Registrar vigencia, Incoterm y condiciones de pago en cada cotización de proveedor; recotizar si está vencida.", "responsable": "Fabian Burgos (Compras)", "fecha_terminacion": "", "fecha_verificacion": "", "acciones_tomadas": "", "severidad_r": null, "ocurrencia_r": null, "deteccion_r": null}]}, {"id": "ng0v7xvn04ij", "actividad": "Respuesta de cotizaciones a ventas", "modos": [{"id": "3kvv3w2v8icq", "modo": "Costo mal calculado al cotizar a ventas (sin flete, aranceles, gastos de aduana o tipo de cambio)", "efectos": "Venta con margen bajo o con pérdida, precio que luego no se puede sostener", "vinculado": "Objetivo de calidad", "tipo": "riesgo", "severidad": 4, "causas": "Se cotiza con el precio del proveedor sin sumar todo el costo puesto en México", "ocurrencia": 2, "prevencion": "Costos y margen capturados en el portal por partida", "deteccion_ctrl": "Revisión de margen en la cotización", "deteccion": 3, "acciones": "Usar un cálculo de costo puesto en almacén (precio + flete + arancel + aduana + tipo de cambio) para artículos de importación.", "responsable": "Fabian Burgos (Compras)", "fecha_terminacion": "", "fecha_verificacion": "", "acciones_tomadas": "", "severidad_r": null, "ocurrencia_r": null, "deteccion_r": null}, {"id": "jcq5caqo2vso", "modo": "Respuesta tardía a la solicitud del vendedor", "efectos": "Pérdida de la venta, cliente insatisfecho", "vinculado": "Cliente", "tipo": "riesgo", "severidad": 3, "causas": "Carga de trabajo, espera de respuesta del proveedor", "ocurrencia": 4, "prevencion": "Plazo de respuesta configurado en el portal", "deteccion_ctrl": "Alertas automáticas del portal de solicitudes fuera de plazo", "deteccion": 2, "acciones": "Atender primero las solicitudes vencidas o por vencer del inicio del portal.", "responsable": "Fabian Burgos (Compras)", "fecha_terminacion": "", "fecha_verificacion": "", "acciones_tomadas": "", "severidad_r": null, "ocurrencia_r": null, "deteccion_r": null}]}, {"id": "xpperr0vhmeq", "actividad": "Orden de compra", "modos": [{"id": "rn5fnsjfuwln", "modo": "Compra sin orden de compra", "efectos": "Compra no autorizada, descontrol presupuestal, no existe trazabilidad", "vinculado": "Cláusula ISO 9001", "tipo": "riesgo", "severidad": 4, "causas": "Compra urgente o de bajo monto hecha por teléfono o correo", "ocurrencia": 1, "prevencion": "Toda compra se hace con OC en el portal", "deteccion_ctrl": "Conciliación de facturas contra OC", "deteccion": 2, "acciones": "", "responsable": "", "fecha_terminacion": "", "fecha_verificacion": "", "acciones_tomadas": "", "severidad_r": null, "ocurrencia_r": null, "deteccion_r": null}, {"id": "obu2e2v9eodh", "modo": "OC sin autorización", "efectos": "Gasto fuera de presupuesto, compra innecesaria", "vinculado": "Proceso", "tipo": "riesgo", "severidad": 3, "causas": "La revisión con la gerente es de palabra y no queda registro", "ocurrencia": 2, "prevencion": "Revisión de cada OC con la gerente", "deteccion_ctrl": "Ninguno registrado", "deteccion": 3, "acciones": "Dejar registro de la revisión de la gerente en la OC (visto bueno en el portal o firma).", "responsable": "Fabian Burgos (Compras) y gerente", "fecha_terminacion": "", "fecha_verificacion": "", "acciones_tomadas": "", "severidad_r": null, "ocurrencia_r": null, "deteccion_r": null}, {"id": "wqui8l9da2kh", "modo": "OC con datos erróneos o que cambia al embarcar", "efectos": "Pago incorrecto, material incompleto, diferencia de inventario", "vinculado": "Proveedor", "tipo": "riesgo", "severidad": 3, "causas": "La OC de importación se hace antes de saber lo que realmente cabe en el contenedor; al final cambian cantidades", "ocurrencia": 4, "prevencion": "Revisión de la OC con la gerente", "deteccion_ctrl": "Comparación contra la factura y lista de empaque hasta el final", "deteccion": 4, "acciones": "Actualizar la OC (revisión) cuando el proveedor confirme la lista de empaque, antes de pagar el saldo.", "responsable": "Fabian Burgos (Compras)", "fecha_terminacion": "", "fecha_verificacion": "", "acciones_tomadas": "", "severidad_r": null, "ocurrencia_r": null, "deteccion_r": null}]}, {"id": "3xel0z51uk1j", "actividad": "Seguimiento a entregas", "modos": [{"id": "rbyv420w8rc7", "modo": "Entrega fuera de tiempo / retraso (principalmente China)", "efectos": "Pérdida de venta, flete urgente, multa de cliente", "vinculado": "Cliente", "tipo": "riesgo", "severidad": 4, "causas": "Tiempos de producción, puerto, naviera, aduana y temporadas (Año Nuevo Chino); lo de China llega tarde en casi cada embarque, los locales rara vez", "ocurrencia": 5, "prevencion": "Ninguno formal: se pide con anticipación sin un tiempo de entrega real por proveedor", "deteccion_ctrl": "Seguimiento con el proveedor y el agente aduanal: el retraso se ve cuando ya pasó", "deteccion": 4, "acciones": "1) Sacar el tiempo real de entrega de cada proveedor de China (pedido, producción, tránsito y aduana) y pedir con ese tiempo más un colchón. 2) Pedir a cada proveedor la fecha confirmada de embarque y el número de booking o BL, y revisar cada semana las OC abiertas con su fecha estimada de llegada. 3) Avisar a la jefa de ventas en cuanto un embarque se retrase más de una semana. 4) Definir stock de seguridad de los artículos importados de mayor venta (con la gerente).", "responsable": "Fabian Burgos (Compras); gerente para el stock de seguridad", "fecha_terminacion": "2026-12-14", "fecha_verificacion": "", "acciones_tomadas": "", "severidad_r": null, "ocurrencia_r": null, "deteccion_r": null}, {"id": "1y3jg0outzy2", "modo": "No dar seguimiento al pedido", "efectos": "Desconocimiento de estatus, incumplimiento a clientes", "vinculado": "Cliente", "tipo": "riesgo", "severidad": 4, "causas": "Muchas OC abiertas al mismo tiempo sin un control único", "ocurrencia": 2, "prevencion": "Registro de OC en el portal", "deteccion_ctrl": "Revisión de OC abiertas", "deteccion": 3, "acciones": "Revisión semanal de OC abiertas con su estatus.", "responsable": "Fabian Burgos (Compras)", "fecha_terminacion": "", "fecha_verificacion": "", "acciones_tomadas": "", "severidad_r": null, "ocurrencia_r": null, "deteccion_r": null}, {"id": "llq4l5fk1qjx", "modo": "Aviso de retraso a último momento", "efectos": "Sin tiempo de reacción, compra de emergencia con costo elevado", "vinculado": "Proveedor", "tipo": "riesgo", "severidad": 4, "causas": "El proveedor no avisa hasta la fecha de embarque", "ocurrencia": 3, "prevencion": "Ninguno formal", "deteccion_ctrl": "Solo se detecta cuando no llega", "deteccion": 4, "acciones": "Pedir al proveedor confirmación de fecha de embarque y número de guía o BL una semana antes.", "responsable": "Fabian Burgos (Compras)", "fecha_terminacion": "", "fecha_verificacion": "", "acciones_tomadas": "", "severidad_r": null, "ocurrencia_r": null, "deteccion_r": null}]}, {"id": "oh6993n8evrb", "actividad": "Recepción e inspección (entrada de la compra con factura)", "modos": [{"id": "h60inqtbtvdx", "modo": "Material no conforme / dañado", "efectos": "Devolución, retrabajo, reclamo del cliente, paro del proceso operativo", "vinculado": "Producto", "tipo": "riesgo", "severidad": 4, "causas": "Falla de calidad del proveedor o daño en tránsito", "ocurrencia": 2, "prevencion": "Evaluación de proveedores", "deteccion_ctrl": "Inspección de almacén al recibir", "deteccion": 3, "acciones": "Que almacén reporte a compras el mismo día cualquier daño para reclamar al proveedor o a la aseguradora.", "responsable": "Almacén y Fabian Burgos (Compras)", "fecha_terminacion": "", "fecha_verificacion": "", "acciones_tomadas": "", "severidad_r": null, "ocurrencia_r": null, "deteccion_r": null}, {"id": "bjb99uip8bbf", "modo": "Cantidad diferente a la OC", "efectos": "Faltante para vender, sobrante, inventario incorrecto", "vinculado": "Proceso", "tipo": "riesgo", "severidad": 3, "causas": "Lo embarcado cambia según lo que cabe en el contenedor", "ocurrencia": 4, "prevencion": "Lista de empaque del proveedor", "deteccion_ctrl": "Conteo de almacén y entrada de la compra con factura", "deteccion": 3, "acciones": "Conciliar OC, lista de empaque, factura y conteo de almacén al dar entrada a la compra.", "responsable": "Fabian Burgos (Compras) y almacén", "fecha_terminacion": "", "fecha_verificacion": "", "acciones_tomadas": "", "severidad_r": null, "ocurrencia_r": null, "deteccion_r": null}, {"id": "jbqr6sze0qu9", "modo": "Material sin certificado / lote", "efectos": "No conformidad, sin rastreabilidad (requisito de identificación y trazabilidad de ISO 9001 y de algunos clientes)", "vinculado": "Cláusula ISO 9001", "tipo": "riesgo", "severidad": 5, "causas": "No hay control de lote: solo algunos artículos traen lote del proveedor y la mayoría no; no está definido qué artículos lo requieren", "ocurrencia": 3, "prevencion": "Ninguno", "deteccion_ctrl": "Ninguno", "deteccion": 5, "acciones": "1) Hacer la lista de artículos y clientes que requieren lote o certificado. 2) Ponerlo como requisito en la OC de esos artículos y no pagar el saldo sin el certificado o lote. 3) Que almacén anote el lote al recibir para poder rastrearlo hasta el cliente.", "responsable": "Fabian Burgos (Compras); jefa de ventas para la lista; almacén para registrar el lote", "fecha_terminacion": "2026-12-14", "fecha_verificacion": "", "acciones_tomadas": "", "severidad_r": null, "ocurrencia_r": null, "deteccion_r": null}]}, {"id": "kykwa6gx6ak5", "actividad": "Facturación y precios", "modos": [{"id": "jt1dkssmep72", "modo": "Factura con precio o cantidad diferente a la OC", "efectos": "Pago incorrecto, pérdida económica, diferencia contable", "vinculado": "Proveedor", "tipo": "riesgo", "severidad": 3, "causas": "La OC no se actualiza cuando cambia lo embarcado", "ocurrencia": 4, "prevencion": "Revisión de la OC con la gerente", "deteccion_ctrl": "Comparación de factura contra OC al registrar la compra", "deteccion": 3, "acciones": "Misma acción que OC con datos erróneos: actualizar la OC antes de pagar y conciliar contra la factura.", "responsable": "Fabian Burgos (Compras)", "fecha_terminacion": "", "fecha_verificacion": "", "acciones_tomadas": "", "severidad_r": null, "ocurrencia_r": null, "deteccion_r": null}, {"id": "389x2c4kli5i", "modo": "Factura sin OC o duplicada", "efectos": "Pago duplicado, descontrol, hallazgos en auditoría", "vinculado": "Proceso", "tipo": "riesgo", "severidad": 3, "causas": "Proveedor que envía la factura dos veces o por otro medio", "ocurrencia": 1, "prevencion": "Toda compra con OC", "deteccion_ctrl": "Revisión de pagos en el portal", "deteccion": 3, "acciones": "", "responsable": "", "fecha_terminacion": "", "fecha_verificacion": "", "acciones_tomadas": "", "severidad_r": null, "ocurrencia_r": null, "deteccion_r": null}, {"id": "k9ygshrzjlra", "modo": "Error en condiciones de pago o moneda", "efectos": "Pago anticipado indebido, afectación del flujo", "vinculado": "Proceso", "tipo": "riesgo", "severidad": 4, "causas": "Confusión entre USD y MXN, anticipo y saldo", "ocurrencia": 2, "prevencion": "Moneda y condiciones capturadas en la OC del portal", "deteccion_ctrl": "Revisión del pago antes de mandarlo", "deteccion": 3, "acciones": "", "responsable": "", "fecha_terminacion": "", "fecha_verificacion": "", "acciones_tomadas": "", "severidad_r": null, "ocurrencia_r": null, "deteccion_r": null}]}, {"id": "5ff0w7hoe9nd", "actividad": "Importación y aduana", "modos": [{"id": "xbbw4v2iryqn", "modo": "Carta 3.1.8 o pedimento con datos erróneos", "efectos": "Multa o retención de la mercancía en aduana, retraso", "vinculado": "Requisito legal", "tipo": "riesgo", "severidad": 4, "causas": "Datos de la factura y la OC no coinciden o se capturan a mano", "ocurrencia": 2, "prevencion": "Formato de carta 3.1.8 armado desde la OC y factura", "deteccion_ctrl": "Revisión del agente aduanal", "deteccion": 3, "acciones": "Revisar la carta contra factura y lista de empaque antes de firmarla.", "responsable": "Fabian Burgos (Compras)", "fecha_terminacion": "", "fecha_verificacion": "", "acciones_tomadas": "", "severidad_r": null, "ocurrencia_r": null, "deteccion_r": null}, {"id": "rmg0ot37aswg", "modo": "Fracción arancelaria equivocada", "efectos": "Pago de impuestos incorrecto, multa, retención", "vinculado": "Requisi